def _compare(first, second):
    colors_a = {value for row in first for value in row}
    colors_b = {value for row in second for value in row}
    shared = colors_a & colors_b
    if not shared:
        raise ValueError("panels have no shared color")
    # The common color is the background used for unequal cells in the
    # examples; select the shared color most frequent across both panels.
    common = max(shared, key=lambda color:
                 sum(row.count(color) for row in first) +
                 sum(row.count(color) for row in second))
    return [[3 if a == b else common for a, b in zip(row_a, row_b)]
            for row_a, row_b in zip(first, second)]


def transform(grid):
    """Compare aligned cells in two equal panels separated by a solid line.

    Equal cells become 3. Unequal cells become the color shared by both
    panels, which is their common background in the demonstrated tasks.
