        if all(row[c] == separator for row in grid) and c == w - c - 1:
            first = [row[:c] for row in grid]
            second = [row[c + 1:] for row in grid]
            return _compare(first, second)

    for r in range(1, h - 1):
        separator = grid[r][0]
        if all(value == separator for value in grid[r]) and r == h - r - 1:
            return _compare(grid[:r], grid[r + 1:])

